using System; using System.Collections.Generic; using System.Collections.ObjectModel; using System.Linq; using System.Runtime.Serialization;
namespace NavisLegacyPlugin.Models.Execution { [DataContract] public sealed class TransferOutcomeSet { public TransferOutcomeSet(string executionId,string sourceFile,string exportSet,string sourceResolution,string targetResolution,TransferExecutionStatus status,IEnumerable<TransferOutcome> outcomes){ExecutionId=executionId??string.Empty;SourceFile=sourceFile??string.Empty;ExportSet=exportSet??string.Empty;SourceResolution=sourceResolution??string.Empty;TargetResolution=targetResolution??string.Empty;Status=status;Outcomes=new ReadOnlyCollection<TransferOutcome>((outcomes??Enumerable.Empty<TransferOutcome>()).ToList());} [DataMember(Order=1)]public string ExecutionId{get;private set;} [DataMember(Order=2)]public string SourceFile{get;private set;} [DataMember(Order=3)]public string ExportSet{get;private set;} [DataMember(Order=4)]public string SourceResolution{get;private set;} [DataMember(Order=5)]public string TargetResolution{get;private set;} [DataMember(Order=6)]public TransferExecutionStatus Status{get;private set;} [DataMember(Order=7)]public ReadOnlyCollection<TransferOutcome> Outcomes{get;private set;} public int Matched{get{return Outcomes.Count(x=>x.Match.Status==TransferMatchStatus.Matched);}} public int DetailedUnmatched{get{return Outcomes.Count(x=>x.Match.Status==TransferMatchStatus.Unmatched);}} public int Ambiguous{get{return Outcomes.Count(x=>x.Match.Status==TransferMatchStatus.Ambiguous);}} public int MissingKey{get{return Outcomes.Count(x=>x.Match.Status==TransferMatchStatus.MissingKey);}} public int Unmatched{get{return DetailedUnmatched+Ambiguous+MissingKey;}} public int Written{get{return Outcomes.Count(x=>x.OperationStatus==TransferOperationStatus.Written);}} public int Skipped{get{return Outcomes.Count(x=>x.OperationStatus==TransferOperationStatus.Skipped);}} public int Failed{get{return Outcomes.Count(x=>x.OperationStatus==TransferOperationStatus.Failed);}} public int NotApplicable{get{return Outcomes.Count(x=>x.OperationStatus==TransferOperationStatus.NotApplicable);}} } }
